M(core, r"""
public static Object get(String k) {
  try { java.util.Map m = bridge(); return (m == null || k == null) ? null : m.get(k); } catch (Throwable t) { return null; }
}""")
M(core, r"""
public static boolean put(String k, Object v) {
  try {
    if (k == null) return false;
    java.util.Map m = bridge();
    if (v == null) m.remove(k); else m.put(k, v);
    return true;
  } catch (Throwable t) { return false; }
}""")
M(core, r"""
public static Object putIfAbsent(String k, Object v) {
  try { if (k == null || v == null) return null; return bridge().putIfAbsent(k, v); } catch (Throwable t) { return null; }
}""")
M(core, r"""
public static boolean remove(String k, Object v) {
  try { if (k == null || v == null) return false; return bridge().remove(k, v); } catch (Throwable t) { return false; }
}""")
M(core, r"""
public static Object call(String k, Object arg) {
  try {
    Object o = get(k);
    if (!(o instanceof java.util.function.Function)) return null;
    return ((java.util.function.Function) o).apply(arg);
  } catch (Throwable t) { return null; }
}""")
M(core, r"""
public static boolean has(String k) {
  return get(k) instanceof java.util.function.Function;
}""")
# fix round (critic: spec 2.1 says Core.fn(key).apply(...) follows the never-throws rule, but fn answered the raw bridge Function or
# null - Core.fn("coins:fn:get").apply(x) threw an NPE with Coins off): fn(key) now answers a SafeFn HANDLE - never null; its apply
# looks the key up on every call (a publisher that starts later is found, one that stops is let go) and answers like call(key, x):
# the publisher's answer, or null when the key is absent / not a Function / the publisher threw. Presence: Core.has(key) or
# handle.live().
sfn = pool.makeClass("com.skyy.core.SafeFn")
sfn.addInterface(pool.get("java.util.function.Function"))
