M(kl, r"""
public static Class dataOf(Class c) {
  if (c == null) return null;
  ClassLoader l = c.getClassLoader();
  if (l instanceof com.skyy.core.KitLoader) return ((com.skyy.core.KitLoader) l).data;
  return null;
}""")
M(kl, r"""
public static boolean isKit(String n) {
  if (n == null) return false;
  for (int i = 0; i < NAMES.length; i++) if (NAMES[i].equals(n)) return true;
  return false;
}""")
M(kl, r"""
public static byte[] bytesOf(String n) throws java.io.IOException {
  Object o = BYTES.get(n);
  if (o != null) return (byte[]) o;
  java.io.InputStream in = com.skyy.core.KitLoader.class.getClassLoader().getResourceAsStream(n.replace('.', '/') + ".class");
  if (in == null) throw new java.io.IOException("not in SkyyCore's jar: " + n);
  byte[] b = null;
  try { b = in.readAllBytes(); } finally { in.close(); }
  BYTES.put(n, b);
  return b;
}""")
M(kl, r"""
protected synchronized Class loadClass(String n, boolean resolve) throws ClassNotFoundException {
  if (!isKit(n)) return super.loadClass(n, resolve);
  Class c = findLoadedClass(n);
  if (c == null) {
    byte[] b = null;
    try { b = bytesOf(n); } catch (Throwable t) { throw new ClassNotFoundException(n + " (SkyyCore config kit template unreadable: " + t + ")"); }
    c = defineClass(n, b, 0, b.length);
    this.defined = this.defined + 1;
  }
  if (resolve) resolveClass(c);
  return c;
}""")
M(kl, 'public String toString() { return "SkyyCore KitLoader[" + (this.data == null ? "-" : this.data.getName()) + "]"; }')

