# the handle of one module's CfgData (SkyyCore's KitLoader defines that module's private kit copy); the same Class -> the same handle
M(cfg, r"""
public static synchronized com.skyy.core.cfg.Cfg open(Class data) {
  if (data == null) {
    com.skyy.core.cfg.Cfg d = new com.skyy.core.cfg.Cfg(null);
    d.error = new IllegalArgumentException("no CfgData class");
    return d;
  }
  Object o = OPEN.get(data);
  if (o != null) return (com.skyy.core.cfg.Cfg) o;
  com.skyy.core.cfg.Cfg c = new com.skyy.core.cfg.Cfg(data);
  try {
    c.mod = String.valueOf(data.getField("MOD").get(null));
    c.loader = new com.skyy.core.KitLoader(data.getClassLoader(), data);
    for (int i = 0; i < KIT.length; i++) c.k[i] = Class.forName("com.skyy.core.cfg." + KIT[i], true, c.loader);
  } catch (Throwable t) {
    c.error = t;
    com.skyy.core.Core.warn(c.mod, "the Server Setup kit (SkyyCore config kit) could not load: " + t + " - the mod runs on its file values; Server Setup for it is off");
  }
  OPEN.put(data, c);
  return c;
}""")
M(cfg, "public boolean ok() { return this.error == null && this.k[0] != null && this.k[6] != null; }")
M(cfg, "public String mod() { return this.mod; }")
