def sig(s):
    return "new Class[] { " + ", ".join(SIG[ch] for ch in s) + " }" if s else "new Class[0]"


# the module's own calls: never throw (a failure is one WARN line through the module's logger, the documented fallback answer)
# start + ONE info line through the module's logger: the proof (server log) that its private kit copy runs and published config:fn
M(cfg, r"""
public void start(java.nio.file.Path modsDir, @LOG@ log) {
  try {
    call(6, "start", %s, new Object[] { modsDir, log });
    Object f = com.skyy.core.Core.get("config:fn:" + this.mod);
    int rows = -1;
    try { rows = ((String[]) get(0, "KEYS")).length; } catch (Throwable t2) { }
    String msg = "Server Setup kit " + get(0, "KIT") + " from SkyyCore " + com.skyy.core.Core.version() + ": " + rows + " rows, folder " + get(0, "HOMEDIR") + ", config:fn:" + this.mod + (f instanceof java.util.function.Function ? " published" : " NOT published");
    if (log != null) log.at(java.util.logging.Level.INFO).log("[" + this.mod + "] " + msg); else com.skyy.core.Core.info(this.mod, msg);
  } catch (Throwable t) { fail("start", t); }
}""" % sig("PL"))
